DROP TABLE IF EXISTS `fakta_kebutuhan_keahlian`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fakta_kebutuhan_keahlian` (
  `kebutuhan_key` bigint unsigned NOT NULL AUTO_INCREMENT,
  `syarat_id` bigint unsigned NOT NULL,
  `waktu_key` int unsigned NOT NULL,
  `keahlian_key` int unsigned NOT NULL,
  `lowongan_key` int unsigned NOT NULL,
  `perusahaan_key` int unsigned NOT NULL,
  `lokasi_key` int unsigned NOT NULL,
  `jumlah_kebutuhan` tinyint unsigned NOT NULL DEFAULT '1',
  `is_wajib` tinyint unsigned NOT NULL,
  `wajib_terverifikasi` tinyint unsigned NOT NULL,
  `bobot` decimal(5,2) NOT NULL,
  PRIMARY KEY (`kebutuhan_key`),
  UNIQUE KEY `syarat_id` (`syarat_id`),
  KEY `waktu_key` (`waktu_key`),
  KEY `keahlian_key` (`keahlian_key`),
  KEY `lowongan_key` (`lowongan_key`),
  KEY `perusahaan_key` (`perusahaan_key`),
  KEY `lokasi_key` (`lokasi_key`),
  CONSTRAINT `fakta_kebutuhan_keahlian_ibfk_1` FOREIGN KEY (`waktu_key`) REFERENCES `dim_waktu` (`waktu_key`),
  CONSTRAINT `fakta_kebutuhan_keahlian_ibfk_2` FOREIGN KEY (`keahlian_key`) REFERENCES `dim_keahlian` (`keahlian_key`),
  CONSTRAINT `fakta_kebutuhan_keahlian_ibfk_3` FOREIGN KEY (`lowongan_key`) REFERENCES `dim_lowongan` (`lowongan_key`),
  CONSTRAINT `fakta_kebutuhan_keahlian_ibfk_4` FOREIGN KEY (`perusahaan_key`) REFERENCES `dim_perusahaan` (`perusahaan_key`),
  CONSTRAINT `fakta_kebutuhan_keahlian_ibfk_5` FOREIGN KEY (`lokasi_key`) REFERENCES `dim_lokasi` (`lokasi_key`)
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
