DROP TABLE IF EXISTS `fakta_verifikasi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fakta_verifikasi` (
  `verifikasi_key` bigint unsigned NOT NULL AUTO_INCREMENT,
  `verifikasi_id` bigint unsigned NOT NULL,
  `waktu_key` int unsigned NOT NULL,
  `verifikator_key` int unsigned NOT NULL,
  `jenis_bukti_key` int unsigned NOT NULL,
  `jumlah_verifikasi` tinyint unsigned NOT NULL DEFAULT '1',
  `disetujui` tinyint unsigned NOT NULL,
  `ditolak` tinyint unsigned NOT NULL,
  `durasi_jam` int unsigned NOT NULL,
  PRIMARY KEY (`verifikasi_key`),
  UNIQUE KEY `verifikasi_id` (`verifikasi_id`),
  KEY `waktu_key` (`waktu_key`),
  KEY `verifikator_key` (`verifikator_key`),
  KEY `jenis_bukti_key` (`jenis_bukti_key`),
  CONSTRAINT `fakta_verifikasi_ibfk_1` FOREIGN KEY (`waktu_key`) REFERENCES `dim_waktu` (`waktu_key`),
